/* Original generated Japanese castle surface studies; encoded for offline 3D materials. */
(function (root) {
  "use strict";
  const SURFACES = {"stone":"data:image/jpeg;base64,","earth":"data:image/jpeg;base64,","plaster":"data:image/jpeg;base64,"};
  const PALETTE = { stone: "#827e73", earth: "#987b4c", plaster: "#e5e1d5" };

  function createTextures(THREE, options = {}) {
    if (!THREE?.CanvasTexture || !root.document?.createElement || !root.Image) return null;
    const canvases = {};
    for (const name of Object.keys(SURFACES)) {
      const canvas = root.document.createElement("canvas");
      canvas.width = canvas.height = 512;
      const context = canvas.getContext("2d");
      if (!context) return null;
      context.fillStyle = PALETTE[name];
      context.fillRect(0, 0, 512, 512);
      canvases[name] = { canvas, context };
    }
    const maps = {};
    const pending = [];
    const images = new Set();
    let disposed = false;
    for (const [name, uri] of Object.entries(SURFACES)) {
      const { canvas, context } = canvases[name];
      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.anisotropy = Math.max(1, Math.min(8, Number(options.anisotropy) || 1));
      texture.repeat?.set(1, 1);
      texture.name = `tenka-fortress-${name}`;
      maps[name] = texture;
      pending.push(new Promise((resolve) => {
        const image = new root.Image();
        let settled = false;
        const finish = (loaded) => {
          if (settled) return;
          settled = true;
          images.delete(image);
          image.onload = image.onerror = null;
          if (loaded && !disposed) {
            try {
              context.drawImage(image, 0, 0, 512, 512);
              texture.needsUpdate = true;
            } catch (_) { loaded = false; }
            if (loaded) {
              try { options.onLoad?.(name); } catch (_) { /* Loading must still settle. */ }
            }
          }
          resolve(loaded && !disposed);
        };
        image.onload = () => finish(true);
        image.onerror = () => finish(false);
        image._tenkaCancel = () => finish(false);
        images.add(image);
        try { image.src = uri; } catch (_) { finish(false); }
      }));
    }
    maps.ready = Promise.all(pending);
    maps.dispose = () => {
      if (disposed) return;
      disposed = true;
      for (const image of images) image._tenkaCancel();
      images.clear();
      for (const name of Object.keys(SURFACES)) maps[name].dispose();
    };
    return maps;
  }

  root.TenkaFortressMaterials = Object.freeze({ createTextures, version: 1 });
})(typeof window !== "undefined" ? window : globalThis);
